INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 English Grammar, Punctuation and Spelling Vocabulary Practice', 'This quiz focuses on vocabulary related to English grammar, punctuation, and spelling as presented in the 2018 Key Stage 2 national curriculum test. It helps students understand terms such as prefixes, clauses, punctuation marks, word classes, and sentence types, enhancing their language skills and comprehension.', '[{"id": "q1", "type": "mcq", "question": "What does the prefix ''re-'' mean in the word ''replay''?", "hint": "Think about what happens when you replay something.", "explanation": "The prefix ''re-'' means ''again'', so ''replay'' means to play again.", "correctAnswer": "c", "options": [{"id": "a", "text": "to play together"}, {"id": "b", "text": "to play later"}, {"id": "c", "text": "to play again"}, {"id": "d", "text": "to play badly"}]}, {"id": "q2", "type": "mcq", "question": "Which sentence must end with a question mark?", "hint": "Look for a sentence that asks something.", "explanation": "A question mark is used at the end of a sentence that asks a question.", "correctAnswer": "b", "options": [{"id": "a", "text": "What happened that day might never be known"}, {"id": "b", "text": "What really happened that day"}, {"id": "c", "text": "Someone must know what really happened that day"}, {"id": "d", "text": "I\u2019d like to know what happened that day"}]}, {"id": "q3", "type": "mcq", "question": "Which word is an adverb in the sentence: ''The lively crowd cheered loudly when the rally car race began.''?", "hint": "Adverbs often describe how an action is done.", "explanation": "''Loudly'' describes how the crowd cheered, so it is the adverb.", "correctAnswer": "c", "options": [{"id": "a", "text": "lively"}, {"id": "b", "text": "cheered"}, {"id": "c", "text": "loudly"}, {"id": "d", "text": "race"}]}, {"id": "q4", "type": "fillInBlank", "question": "Complete the sentence with the correct noun formed from the verb invent: The engineer thought her latest ___ would solve the problem.", "hint": "The noun form of invent often ends with ''-ion''.", "explanation": "The noun formed from ''invent'' is ''invention'', which means something newly created.", "correctAnswer": "invention"}, {"id": "q5", "type": "multiSelect", "question": "Which of the following sentences use punctuation to show parenthesis?", "hint": "Parenthesis is extra information added to a sentence, often set off by commas, dashes, or brackets.", "explanation": "Parenthesis is shown by punctuation that adds extra information without changing the main meaning.", "correctAnswer": ["a", "c"], "options": [{"id": "a", "text": "There are some books \u2013 including story books \u2013 in the cupboard."}, {"id": "b", "text": "To make space, we moved the chairs, tables and the boxes of games."}, {"id": "c", "text": "Our classroom, at the end of the corridor, has a red door."}, {"id": "d", "text": "On Tuesday, we will be selling cakes for charity."}]}, {"id": "q6", "type": "mcq", "question": "Which sentence is written in Standard English?", "hint": "Standard English follows correct grammar and tense rules.", "explanation": "The sentence ''My friend was tidying the classroom.'' uses correct past tense and grammar.", "correctAnswer": "b", "options": [{"id": "a", "text": "Two sports teams come to our school yesterday."}, {"id": "b", "text": "My friend was tidying the classroom."}, {"id": "c", "text": "Today the children done their school play."}, {"id": "d", "text": "The teachers was going to send a letter next week."}]}, {"id": "q7", "type": "mcq", "question": "Which verb is a synonym of the verb ''produce''?", "hint": "Think about a word that means to make or create something.", "explanation": "''Make'' means to create or produce something, so it is a synonym.", "correctAnswer": "a", "options": [{"id": "a", "text": "make"}, {"id": "b", "text": "buy"}, {"id": "c", "text": "sell"}, {"id": "d", "text": "trade"}]}, {"id": "q8", "type": "fillInBlank", "question": "Insert a subordinating conjunction to complete the sentence: We listened to the music ___ we ate our lunch.", "hint": "This conjunction shows two actions happening at the same time.", "explanation": "The subordinating conjunction ''while'' shows that two actions happen simultaneously.", "correctAnswer": "while"}, {"id": "q9", "type": "mcq", "question": "Which sentence is a command?", "hint": "Commands tell someone to do something.", "explanation": "A command gives an instruction, such as ''Bring a coat in case it rains.''", "correctAnswer": "d", "options": [{"id": "a", "text": "You should bring a coat."}, {"id": "b", "text": "You will need a coat in case it rains."}, {"id": "c", "text": "I am going to bring a coat."}, {"id": "d", "text": "Bring a coat in case it rains."}]}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 Spelling and Vocabulary Practice', 'This quiz focuses on vocabulary and spelling skills based on the 2018 Key Stage 2 English grammar, punctuation, and spelling test. Students will practice word meanings, correct spelling, and usage in context to improve their language proficiency.', '[{"id": "q1", "type": "fillInBlank", "question": "Mum hit her ___ with the hammer.", "hint": "This word is a body part often used for holding things.", "explanation": "The correct answer is ''thumb''. It is a part of the hand and is often used to grip or hold objects.", "correctAnswer": "thumb"}, {"id": "q2", "type": "mcq", "question": "Which word best completes the sentence: ''The boy had ___ keeping up with his elder sister.''?", "hint": "Think of a word that means difficulty or trouble.", "explanation": "The correct answer is ''trouble'' because it means difficulty or problems, which fits the context of struggling to keep up.", "correctAnswer": "a", "options": [{"id": "a", "text": "trouble"}, {"id": "b", "text": "fun"}, {"id": "c", "text": "luck"}, {"id": "d", "text": "joy"}]}, {"id": "q3", "type": "multiSelect", "question": "Select all words that can describe something light and easy to carry.", "hint": "Think about synonyms for ''light'' in terms of weight.", "explanation": "The words ''light'' and ''portable'' both describe something that is easy to carry or not heavy.", "correctAnswer": ["b", "c"], "options": [{"id": "a", "text": "heavy"}, {"id": "b", "text": "light"}, {"id": "c", "text": "portable"}, {"id": "d", "text": "bulky"}, {"id": "e", "text": "weighty"}]}, {"id": "q4", "type": "fillInBlank", "question": "Raif ___ his parents\u2019 permission to go out.", "hint": "This word means to ask for or get approval.", "explanation": "The correct answer is ''asked''. It means Raif requested permission from his parents.", "correctAnswer": "asked"}, {"id": "q5", "type": "mcq", "question": "What is the best word to complete this sentence? ''Water is ___ to life.''", "hint": "Think of a word that means absolutely necessary.", "explanation": "The correct answer is ''essential'' because water is absolutely necessary for life.", "correctAnswer": "b", "options": [{"id": "a", "text": "optional"}, {"id": "b", "text": "essential"}, {"id": "c", "text": "unimportant"}, {"id": "d", "text": "unnecessary"}]}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 English Grammar, Punctuation, and Spelling Vocabulary Practice', 'This quiz focuses on vocabulary related to English grammar, punctuation, and spelling as presented in the 2024 Key Stage 2 national curriculum test. It helps students understand terms such as punctuation marks, parts of speech, grammatical structures, and word formation to improve their language skills.', '[{"id": "q1", "type": "mcq", "question": "Which word is a synonym of ''happy''?", "hint": "Think of a word that means feeling pleased or joyful.", "explanation": "The word ''contented'' means feeling satisfied and happy, making it a synonym of ''happy''.", "correctAnswer": "a", "options": [{"id": "a", "text": "contented"}, {"id": "b", "text": "bored"}, {"id": "c", "text": "cheerful"}, {"id": "d", "text": "miserable"}]}, {"id": "q2", "type": "mcq", "question": "Which sentence must end with a question mark?", "hint": "Look for a sentence that asks something.", "explanation": "A question mark is used at the end of a sentence that asks a direct question.", "correctAnswer": "a", "options": [{"id": "a", "text": "Do you know how long it took for the trees to grow"}, {"id": "b", "text": "We have planted rose bushes around the trees"}, {"id": "c", "text": "How beautiful the flowers will be"}, {"id": "d", "text": "I will ask my teacher if I can show you"}]}, {"id": "q3", "type": "multiSelect", "question": "Which of the following words are possessive pronouns?", "hint": "Possessive pronouns show ownership.", "explanation": "Possessive pronouns include words like ''mine'' and ''yours'' which indicate possession.", "correctAnswer": ["a", "c"], "options": [{"id": "a", "text": "mine"}, {"id": "b", "text": "which"}, {"id": "c", "text": "yours"}, {"id": "d", "text": "that"}]}, {"id": "q4", "type": "fillInBlank", "question": "Add a prefix to the word ''mature'' to make its antonym: ___mature", "hint": "The prefix often means ''not'' or ''opposite of''.", "explanation": "Adding the prefix ''im'' to ''mature'' forms ''immature'', which means not mature or opposite in meaning.", "correctAnswer": "immature"}, {"id": "q5", "type": "mcq", "question": "Which sentence uses an apostrophe correctly?", "hint": "An apostrophe shows possession or a contraction.", "explanation": "The sentence ''The car\u2019s horn beeps loudly.'' correctly uses an apostrophe to show possession (the horn belongs to the car).", "correctAnswer": "a", "options": [{"id": "a", "text": "The car\u2019s horn beeps loudly."}, {"id": "b", "text": "The cars\u2019 horn beeps loudly."}, {"id": "c", "text": "The cars horn beep\u2019s loudly."}, {"id": "d", "text": "The cars horn beeps\u2019 loudly."}]}, {"id": "q6", "type": "mcq", "question": "What is the grammatical term for the underlined words in the sentence: ''The cat that was stuck in the tree belongs to my sister.''?", "hint": "This term describes a clause that gives more information about a noun.", "explanation": "A relative clause provides extra information about a noun and usually begins with a relative pronoun like ''that''.", "correctAnswer": "b", "options": [{"id": "a", "text": "a noun phrase"}, {"id": "b", "text": "a relative clause"}, {"id": "c", "text": "a co-ordinating conjunction"}, {"id": "d", "text": "a main clause"}]}, {"id": "q7", "type": "fillInBlank", "question": "Rewrite the verb ''collects'' in the simple past tense: Oliver ___ his medal.", "hint": "Simple past tense often ends with -ed for regular verbs.", "explanation": "The simple past tense of ''collect'' is ''collected'', indicating the action happened in the past.", "correctAnswer": "collected"}, {"id": "q8", "type": "mcq", "question": "Which sentence is the most formal?", "hint": "Formal sentences often use polite and precise language.", "explanation": "The sentence ''The school would benefit from the financial savings.'' uses formal language appropriate for official or academic contexts.", "correctAnswer": "c", "options": [{"id": "a", "text": "The school would save so much money, wouldn\u2019t it?"}, {"id": "b", "text": "The school could end up better off financially."}, {"id": "c", "text": "The school would benefit from the financial savings."}, {"id": "d", "text": "It\u2019s a great idea to save school funds!"}]}, {"id": "q9", "type": "multiSelect", "question": "Which of the following pairs are antonyms?", "hint": "Antonyms are words with opposite meanings.", "explanation": "''Rough'' and ''smooth'' are opposites, as are ''vivid'' and ''dull''. ''Courageous'' and ''brave'' are synonyms, not antonyms.", "correctAnswer": ["a", "c"], "options": [{"id": "a", "text": "rough, smooth"}, {"id": "b", "text": "courageous, brave"}, {"id": "c", "text": "vivid, dull"}]}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO vocab_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ('Key Stage 2 Spelling and Vocabulary Practice', 'This quiz focuses on vocabulary related to spelling and word usage from the 2024 Key Stage 2 English grammar, punctuation, and spelling test. It helps students practice word meanings, synonyms, and correct usage in context.', '[{"id": "q1", "type": "fillInBlank", "question": "Our dogs are ___ and full of energy.", "hint": "Think of a word that means lively and active.", "explanation": "The correct word is ''playful'', which means full of fun and energy, often used to describe animals or children.", "correctAnswer": "playful"}, {"id": "q2", "type": "mcq", "question": "Which word best completes the sentence: \"The swans nested on an ___ in the lake.\"?", "hint": "It is a small piece of land surrounded by water.", "explanation": "The correct answer is ''island'', which means a piece of land surrounded by water.", "correctAnswer": "a", "options": [{"id": "a", "text": "island"}, {"id": "b", "text": "bridge"}, {"id": "c", "text": "hill"}, {"id": "d", "text": "forest"}]}, {"id": "q3", "type": "multiSelect", "question": "Select all words that can mean ''a sign or symbol of friendship or agreement''.", "hint": "Think about words related to friendship tokens or agreements.", "explanation": "Both ''bracelet'' and ''token'' can represent a symbol of friendship or agreement.", "correctAnswer": ["a", "b"], "options": [{"id": "a", "text": "bracelet"}, {"id": "b", "text": "token"}, {"id": "c", "text": "minibus"}, {"id": "d", "text": "dentist"}, {"id": "e", "text": "swans"}]}, {"id": "q4", "type": "fillInBlank", "question": "It is important to stay safe on ___ media.", "hint": "This type of media involves online platforms where people communicate.", "explanation": "The correct answer is ''social'', referring to social media platforms where people interact online.", "correctAnswer": "social"}, {"id": "q5", "type": "mcq", "question": "Which word means ''to increase the chance of something happening''?", "hint": "It is often used when talking about improving success.", "explanation": "The word ''improve'' means to make something better or increase the chance of success.", "correctAnswer": "a", "options": [{"id": "a", "text": "improve"}, {"id": "b", "text": "destroy"}, {"id": "c", "text": "ignore"}, {"id": "d", "text": "reduce"}]}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

